    blend: string;
    /** With blend: clips and the parameter's values where each plays alone, comma separated ("idle 0, walk 2, run 6"); with two parameters, two values each ("idle 0 0, forward 0 1, left -1 0"). */
    clips: string;
    /** Playback rate in this state. */
